          "starterCode": "public class Employee {\n    private int id;\n    private String name;\n    private double standardSalary;\n    // TODO: Employee(), Employee(id, name, standardSalary),\n    // getId, getName (uppercase), getStandardSalary\n}\n\nclass Professor extends Employee {\n    private String department;\n    // TODO: Professor(), Professor(id, name, standardSalary, department),\n    // getDepartment() (uppercase),\n    // calculateActualSalary() (standardSalary * K; GD/gd->1.5, IT/it->2.0, else 1.0),\n    // toString() (\"id, NAME, DEPARTMENT, actualSalary(2dp)\")\n}",
          "sampleSolution": "public class Employee {\n    private int id;\n    private String name;\n    private double standardSalary;\n\n    public Employee() {\n    }\n\n    public Employee(int id, String name, double standardSalary) {\n        this.id = id;\n        this.name = name;\n        this.standardSalary = standardSalary;\n    }\n\n    public int getId() {\n        return id;\n    }\n\n    public String getName() {\n        return name.toUpperCase();\n    }\n\n    public double getStandardSalary() {\n        return standardSalary;\n    }\n}\n\npublic class Professor extends Employee {\n    private String department;\n\n    public Professor() {\n    }\n\n    public Professor(int id, String name, double standardSalary, String department) {\n        super(id, name, standardSalary);\n        this.department = department;\n    }\n\n    public String getDepartment() {\n        return department.toUpperCase();\n    }\n\n    public double calculateActualSalary() {\n        double k;\n        if (department.equalsIgnoreCase(\"GD\")) {\n            k = 1.5;\n        } else if (department.equalsIgnoreCase(\"IT\")) {\n            k = 2.0;\n        } else {\n            k = 1.0;\n        }\n        return getStandardSalary() * k;\n    }\n\n    @Override\n    public String toString() {\n        return getId() + \", \" + getName() + \", \" + getDepartment() + \", \" + String.format(\"%.2f\", calculateActualSalary());\n    }\n}",
